import java.util.List;
import java.util.Map;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

public class SimpleType_construct_TriageGen2Test {

    @Test
    public void testConstruct_ValidClass() {
        Class<?> validClass = String.class;
        SimpleType result = SimpleType.construct(validClass);
        assertNotNull(result);
        assertEquals(validClass, result.getRawClass());
    }














}

